def analyze(n, I, O):
    c=Counter(v for r in I for v in r); bg=c.most_common(1)[0][0]
    cells=[(r,c_,v) for r,row in enumerate(I) for c_,v in enumerate(row) if v!=bg]
    # connected components of non-bg (8-conn)
    seen=set(); comps=[]
    for a,b,v in cells:
        if (a,b) in seen: continue
        comp={(a,b)}; seen.add((a,b)); st=[(a,b)]
        while st:
            p=st.pop(); q=p
            for nr,nc in ((q[0]+1,q[1]),(q[0]-1,q[1]),(q[0],q[1]+1),(q[0],q[1]-1),(q[0]+1,q[1]+1),(q[0]+1,q[1]-1),(q[0]-1,q[1]+1),(q[0]-1,q[1]-1)):
                if 0<=nr<len(I) and 0<=nc<len(I[0]) and (nr,nc) not in seen and I[nr][nc]!=bg:
                    seen.add((nr,nc)); comp.add((nr,nc)); st.append((nr,nc))
        comps.append(comp)
    print('D%d ncomp=%d' % (n,len(comps)))
    for i,comp in enumerate(comps):
        rr=[p[0] for p in comp]; cc=[p[1] for p in comp]
        print(' ',i,'size',len(comp),'box=',min(rr),'..',max(rr),',',min(cc),'..',max(cc),'anchor cell? color at top-left:',I[min(rr)][min(cc)])
    out_cells=[(r,c_,O[r][c_]) for r,row in enumerate(O) for c_,_ in enumerate(row) if O[r][c_]!=bg]
    print('  output added count',len(out_cells)-len([p for p in cells]))
